def section(id,title,body):
    return f'<section class="case-section" id="{id}"><h2>{title}</h2>{body}</section>'

authoring = {
 'title':'An AI draft still needs product judgment.',
 'lede':'Building an exercise-authoring workflow around a learning goal, prompt iteration and explicit review by pedagogy specialists.',
 'focus':'Prompt design, quality validation, engineering direction',
 'period':'2025—2026', 'context':'AI content authoring · EdTech',
 'visual':f'<div class="visual-copy"><span class="eyebrow">Try the workflow</span><h2>The review is part of the product.</h2><p>Explore a simplified example of how a draft can look plausible while testing the wrong skill. The interface and exercise are recreated for this portfolio.</p></div>{workflow("case")}',
 'body': section('context','The workflow before the product.','<p>Creating a curriculum-aligned exercise required both content writing and pedagogical judgment. The opportunity was to help the team produce a useful draft more quickly while retaining a deliberate quality check.</p><p>An early prototype also exposed a practical problem: repeated questions and themes. I discussed adding thematic context with engineering while working out how the generated content would enter the learning workflow.</p>')
 +section('role','What I owned.','<p>I drafted the AI squad’s initial framework and feature options, then worked through the direction with our head of product. I led prompt iteration, coordinated pedagogy review and worked with engineering to deliver the authoring workflow.</p><p class="role-note">I worked alongside the engineer who implemented and deployed the initial generation engine. My part covered the product direction, prompts, expert review and delivery coordination.</p>')
 +section('decisions','The decisions that mattered.','<div class="decision"><h3>A strong instruction does not rescue a weak passage.</h3><p>Pedagogy feedback showed that instructions could work well while the passage was too direct to support meaningful interpretation. I proposed reviewing reusable instructions separately from generated passages and questions, then revised the passage prompt for another expert review.</p></div><div class="decision"><h3>Keep prompt changes comparable.</h3><p>I asked the team to retain earlier prompt versions so changes could be compared. We worked through successive sample batches with pedagogy feedback. When another generated passage might still fall short, I raised curated source material as a possible fallback.</p></div><div class="decision"><h3>Make the handover part of delivery.</h3><p>I coordinated walkthroughs with engineering and the teams who would use the tool. After the internal release, I tracked content through expert revision and asked engineering to integrate the finalised pieces first, rather than wait for the whole batch.</p></div>')
 +section('outcomes','What changed, and what the evidence means.','<div class="outcome-number"><div><strong>~5 hours</strong><span>Team-reported exercise preparation</span></div><div><strong>~1.5 hours</strong><span>AI-assisted workflow, including review</span></div></div><p>The baseline came from asking the pedagogy team how long an exercise took. I timed the automated workflow and included a ten-minute allowance for a quick human review. This is an <strong>approximate workflow comparison</strong>, rather than a controlled productivity study.</p><p>The first version was released internally to pedagogy teams in 2025. The broader initiative produced curriculum-aligned questions for English and Chinese programmes. These demonstrate content production and internal delivery; learner outcomes were not evaluated here.</p><h3>Separate authoring work in 2026</h3><p>I later extended existing question-generation pipelines to work with figures in uploaded teaching material. Teachers could reuse a source figure or work with an illustrative chart, with separate LLM checks for chart validity and whether a question actually relied on the figure. This was a new capability layered onto colleagues’ existing pipelines.</p>')
 +section('reflection','What I would carry forward.','<p>Prompt quality and review design belong in the same product discussion. For the next iteration, I would track review time, the type of corrections required and repeat usage alongside generation time, so the team could see where the workflow still created work.</p>')
}

pathway_demo='''<div class="range-demo" data-pathway-demo><label class="range-top" for="placement-threshold"><span>Illustrative placement threshold</span><output for="placement-threshold">60%</output></label><input id="placement-threshold" type="range" min="30" max="90" step="5" value="60" aria-describedby="threshold-description"><div class="learner-list"><div class="learner" data-learner-score="42"><span>Learner A</span><strong>42%</strong><div class="assignment" data-assignment>Core practice</div></div><div class="learner" data-learner-score="68"><span>Learner B</span><strong>68%</strong><div class="assignment" data-assignment>Extension practice</div></div><div class="learner" data-learner-score="87"><span>Learner C</span><strong>87%</strong><div class="assignment" data-assignment>Extension practice</div></div></div><p class="demo-caption" id="threshold-description">Synthetic learners and scores. A simplified rule, not a live placement system.</p></div>'''
pathways = {
 'title':'One course. A different learning path.',
 'lede':'Designing and delivering a tiered curriculum system that lets a course serve learners at different ability levels, with the tools staff need to operate it.',
 'focus':'Product design, AI-assisted implementation, rollout', 'period':'2026', 'context':'Learning delivery · EdTech',
 'visual':'<div class="visual-copy"><span class="eyebrow">Explore a simple rule</span><h2>Placement has consequences.</h2><p>Move the threshold to see how a rule changes the work assigned to synthetic learners. The real product also needed staff controls, access checks and reporting.</p></div>'+pathway_demo,
 'body':section('context','Different learners, shared operations.','<p>A school needed one course to support different ability levels. That need reached beyond a placement rule: the schedule, practice material, student experience and staff reporting all had to agree about what each learner should receive.</p><p>Feedback from pedagogy and customer success made the staff problem concrete: which activities had a learner completed, which path were they on, and why had particular practice been assigned?</p><p>School schedules also arrived in different document formats and conventions. Turning those requirements into a reusable workflow meant resolving ambiguity before saving a plan.</p>')
 +section('role','What I owned.','<p>I led the design and AI-assisted implementation of the tiered curriculum capabilities, including placement, differentiated delivery and related teacher and admin tools. I also built a document-driven course planner and iterated with pedagogy and customer-success colleagues on real school requirements.</p><p class="role-note">I worked within an existing learning platform, alongside engineers, pedagogy and customer success. My focus was the curriculum and planning workflow, and the staff tools around it.</p>')
 +section('decisions','Make the rules usable, then keep them consistent.','<div class="decision"><h3>Keep one course while serving different work.</h3><p>The course could retain shared structure while learners received different practice. I also had to explain which settings belonged to the source activity, the course or a particular class, so one class’s changes would not silently change another’s setup.</p></div><div class="decision"><h3>Check real scheduling exceptions.</h3><p>A schedule importer needed to handle more than a tidy example. Different grades, revised documents and holiday or exam weeks affected the plan. I used those requirements to shape a preview where staff could resolve ambiguous content matches before saving.</p></div><div class="decision"><h3>Make the learner’s assignment explainable.</h3><p>I translated staff feedback into class views, completion drilldowns and visibility into practice assignments and skill priorities. Those views needed to agree with what a learner could actually access.</p></div>')
 +section('outcomes','Delivery included the operational follow-through.','<p>The implementation added placement and differentiated delivery, plus the staff surfaces needed to operate them. I stayed involved during rollout, including diagnosing and correcting a live placement problem.</p><p>Later work made personalised practice assignments, skill priorities and weekly progress easier for staff to inspect. The evidence here is the delivered workflow and operational follow-through. Learning gains and support-volume changes were not measured for this case study.</p>')
 +section('reflection','A routing rule is only one part of the experience.','<p>A differentiated course creates questions for every person around it: what should this learner receive, why, and what can a teacher change? The staff explanation, correction controls and reporting need as much attention as the placement logic.</p>')
}

quality_demo='''<div class="quality-demo" data-quality-demo><div class="quality-controls" role="group" aria-label="Choose a grading check"><button aria-pressed="true" data-quality-mode="total">Check the total</button><button aria-pressed="false" data-quality-mode="mapping">Check the skill mapping</button></div><table class="grade-table"><caption class="visually-hidden">Synthetic expected and observed skill marks</caption><thead><tr><th scope="col">Skill evidence</th><th scope="col">Expected</th><th scope="col">Observed</th></tr></thead><tbody><tr><th scope="row">Inference</th><td>3</td><td>1</td></tr><tr><th scope="row">Text evidence</th><td>1</td><td>3</td></tr><tr><th scope="row">Total</th><td>4</td><td>4</td></tr></tbody></table><div class="grade-result pass" data-quality-result role="status">Total-only check passes: expected total 4, observed total 4. The skill mismatch is invisible to this check.</div><p class="demo-caption">Fixed synthetic example. This demonstrates a validation distinction, not model accuracy.</p></div>'''
quality={
 'title':'A matching score can still be wrong.',
 'lede':'Extending AI grading preparation with checks against original instructions, score boundaries and skill evidence, plus a recovery path when validation fails.',
 'focus':'Validation design, AI-assisted implementation, review UX', 'period':'2026', 'context':'AI assessment quality · EdTech',
 'visual':'<div class="visual-copy"><span class="eyebrow">Try two ways to check</span><h2>The same total.<br>A different meaning.</h2><p>Compare a total-only check with a check of where marks were attributed. Both totals can match while the underlying skill evidence is wrong.</p></div>'+quality_demo,
 'body':section('context','Readiness needed more than an agreement on totals.','<p>AI-generated grading preparation needed to preserve the original marking policy. A converted rubric could produce the expected total while missing a score boundary, omitting relevant input or attributing marks to the wrong skill.</p><p>The product question was how to make those failures visible and prevent unverified grading from being automatically accepted.</p>')
 +section('role','What I owned.','<p>I added validation against original marking instructions, criterion marks and per-skill evidence, using the same resolved grading configuration intended for student delivery. I also added recovery actions for failed preparation.</p><p class="role-note">My contribution covered validation and recovery. The grading engines were existing platform capabilities built with colleagues.</p>')
 +section('decisions','Check the policy, the boundary and the evidence.','<div class="decision"><h3>Validate the configuration that will actually be used.</h3><p>Preparation checks needed the model answer, marking guidance and governed scoring configuration used by the student grading path.</p></div><div class="decision"><h3>Keep expected judgments independent.</h3><p>Checks considered original attainable scores, paraphrases and missing or contradictory components. Ambiguous original instructions or incomplete required coverage prevented automatic acceptance.</p></div><div class="decision"><h3>Give a failed attempt a useful next step.</h3><p>A repair attempt was checked again against the original cases. When that still failed, staff could review a proposed fix, retain a draft or discard the attempt. A repair could not simply redefine a failing example as correct.</p></div>')
 +section('outcomes','Implemented safeguards, with clear evidence limits.','<p>The delivered workflow exposes validation evidence and blocks automatic acceptance when required checks fail. Tests exercise those guards and the recovery actions.</p><p>The checks establish how the workflow behaves under defined cases. A separate provider benchmark would be needed to make an accuracy claim.</p>')
 +section('reflection','Make uncertainty actionable.','<p>An unexplained “needs review” state transfers the problem to the user. A useful quality workflow shows what failed, why it matters and what can safely happen next.</p>')
}

games={
 'title':'Building learning experiences people can play.',
 'lede':'My foundation in educational game design and development: planning the experience, implementing gameplay and collaborating with a game artist I hired and supervised.',
 'focus':'Game design, implementation, artist hiring and supervision', 'period':'Earlier work', 'context':'Educational games · Earlier public imagery',
 'visual':'<div class="visual-copy"><span class="eyebrow">Earlier public work</span><h2>From the idea<br>to the playable thing.</h2><p>Previously published game imagery from my existing portfolio. It reflects my earlier work, rather than a new standalone game demo.</p></div><img class="case-game-image" src="../assets/educational-game.png" alt="A previously published educational multiplayer trivia game" width="600" height="400">',
 'body':section('context','An interaction has to work in someone’s hands.','<p>My earlier career centred on casual and educational games. At MeeOpp, I planned, designed and implemented game experiences, then hired and supervised a freelance game artist.</p><p>That work made the relationship between product decisions, technical constraints and the experience on a learner’s device concrete.</p>')
 +section('role','What I owned.','<p>I worked across game planning, design and implementation. I also onboarded the artist, briefed tasks, reviewed assets and coordinated how the work would fit with animation and the game. My broader game-development background includes gameplay systems and interactive prototypes across several studios.</p><p class="role-note">The artwork was created by the artist and creative colleagues; backend work involved engineers. My role connected the game design, implementation and those handoffs.</p>')
 +section('decisions','Small decisions shape the experience.','<div class="decision"><h3>Balance urgency with a fair chance to participate.</h3><p>When a limited-time game campaign was discussed, I raised the risk that a long extension could weaken its intended urgency. A colleague brought evidence that some learners had discovered it late. We considered the trade-off together as part of the release discussion.</p></div><div class="decision"><h3>Work across the art handoff.</h3><p>The detail mattered: whether an avatar asset would fit another body part, whether animation frames could be reused, and which export format the next team needed. I briefed those requirements, reviewed the work and coordinated changes with the animation team.</p></div><div class="decision"><h3>Improve the route to browser and mobile play.</h3><p>I led the Unity-to-Phaser and TypeScript migration for MeeOpp games, enabling iPad and mobile play and reducing build size.</p></div>')
 +section('outcomes','A foundation I still use.','<p>The game work established experience across product design, implementation and creative collaboration. The migration addressed a practical barrier to access across devices.</p><p><a class="text-link" href="../legacy.html">Browse my earlier public portfolio '+ARROW+'</a></p>')
 +section('reflection','What carries into AI product work.','<p>Prototypes make assumptions visible. Working software exposes constraints that a description can miss. I bring that habit into AI product work, alongside the domain validation and quality checks those workflows require.</p>')
}

feedback_demo = '''<div class="feedback-demo" data-feedback-demo><div class="feedback-evidence"><span class="eyebrow">Fixed synthetic evidence</span><strong>Relevant clue identified.<br>Reasoning needs explaining.</strong><span class="feedback-score">Assessment stays the same: 1 / 2</span></div><div class="quality-controls" role="group" aria-label="Choose the feedback audience"><button aria-pressed="true" data-feedback-level="primary">Primary learner</button><button aria-pressed="false" data-feedback-level="secondary">Secondary learner</button><button aria-pressed="false" data-feedback-level="older">Older learner</button></div><div class="feedback-output" role="status" aria-live="polite" data-feedback-output>You found a useful clue. Next time, explain how it supports your answer.</div><p class="demo-caption">Try another audience. These examples are written for this portfolio, not generated live or taken from learner records.</p></div>'''
feedback = {
 'title':'Feedback a learner can actually use.',
 'lede':'Pedagogy flagged comments that were mechanical, repetitive and too abrupt. I worked through the examples with them, revised the prompts and helped make learner language part of the product.',
 'focus':'Prompt implementation, pedagogy review, design collaboration',
 'period':'2025—2026', 'context':'Learner feedback · EdTech',
 'visual':'<div class="visual-copy"><span class="eyebrow">Try the wording</span><h2>Same evidence.<br>A different reader.</h2><p>A younger learner needs different language from an older one. Changing the wording should still preserve the meaning of the assessment.</p></div>'+feedback_demo,
 'body':section('context','The comment was there. The next step was harder to see.','<p>During pedagogy review, feedback could sound mechanical, repeat the same point or open with what a learner had done wrong. There were also inconsistencies between an earlier assessment and the wording produced by a later prompt.</p><p>In related progress-report work, a teacher told us the language was too technical for students and parents. I brought that feedback to our designer. Producing more text was not enough; the reader needed to understand what to do with it.</p>')
 +section('role','My part in the work.','<p>I reviewed examples with pedagogy, revised lesson-summary prompts and submitted backend changes across three summary formats. I also drafted examples at simple, moderate and advanced language levels, then sought feedback from the domain team.</p><p class="role-note">An engineering colleague integrated the level-based guidance into the wider grading and summary workflows. I worked with our designer on the report experience; the visual design was a collaboration.</p>')
 +section('decisions','What I changed, and why.','<div class="decision"><h3>Give the learner something to act on.</h3><p>I changed prompts to lead with a specific strength, use simpler language and frame improvement as a helpful next step. Pedagogy reviewed the new examples and marked what still needed changing.</p></div><div class="decision"><h3>Keep assessment and explanation consistent.</h3><p>I flagged cases where a later feedback prompt contradicted an earlier mark. A friendlier rewrite still needed to explain the recorded assessment accurately, so the review covered consistency as well as tone.</p></div><div class="decision"><h3>Adapt to the reader.</h3><p>I drafted different language levels instead of using the same register for everyone. The report discussions also led us to simplify the proposed status display and put recommendations into the feedback, following alignment with leadership.</p></div>')
 +section('outcomes','Changes that reached the product.','<p>My revisions to three lesson-summary prompt formats were merged in October 2025. I later added explicit output-language handling. Engineering integrated the level-based guidance into the grading and summary workflows.</p><h3>Later follow-through, 2026</h3><p>On another learning workflow, I traced feedback cut off after an abbreviated title to the sentence splitter used by a filter. I fixed that path and worked on summary checks that were rejecting useful advice. My update to the team distinguished the fixed truncation from generic filler that still needed work.</p><p>The evidence shows prompt changes and pipeline repairs. It does not establish an increase in learning outcomes or that every feedback issue was resolved.</p>')
 +section('reflection','The quality check needs checking too.','<p>A filter can remove a bad claim and accidentally damage useful feedback. I now look at the whole route to the learner: the source evidence, the generated explanation, the filters and the final screen.</p>')
}

cases={'authoring':authoring,'feedback':feedback,'pathways':pathways,'quality':quality,'games':games}
ids=list(cases)
for slug,case in cases.items():
    next_slug=ids[(ids.index(slug)+1)%len(ids)]
    next_title=next(p[4] for p in projects if p[0]==next_slug)
    toc=''.join(f'<a href="#{id}">{title}</a>' for id,title in [('context','The context'),('role','My contribution'),('decisions','Key decisions'),('outcomes','Outcomes & evidence'),('reflection','Reflection')])
    visual_note = 'Game imagery comes from my earlier public portfolio. Current product stories use recreated interfaces and synthetic content.' if slug == 'games' else 'Product visuals and interactive examples are recreated for this portfolio with synthetic content. They are not screenshots of learner records or internal systems.'
    html=head(case['title']+' — Omar Ibrahim',case['lede'],'../')+header('../')+f'''<main class="wrap" id="main"><header class="case-hero"><a class="back-link" href="../index.html#work">{BACK} Back to selected work</a><span class="eyebrow">{case['context']}</span><h1>{case['title']}</h1><p class="case-lede">{case['lede']}</p><dl class="case-meta-grid"><div><dt>Period</dt><dd>{case['period']}</dd></div><div><dt>Environment</dt><dd>Education technology</dd></div><div><dt>My focus</dt><dd>{case['focus']}</dd></div></dl></header><div class="case-visual">{case['visual']}</div><div class="case-layout"><nav class="case-toc" aria-label="In this case study">{toc}</nav><article>{case['body']}<p class="section-footnote">{visual_note}</p><a class="case-next" href="{next_slug}.html"><div><p>Next case study</p><strong>{next_title}</strong></div>{ARROW}</a></article></div></main>'''+footer('../')
    (ROOT/'work'/f'{slug}.html').write_text(html)

print(f'Created homepage and {len(cases)} static case-study pages.')
